        }
      ],
      "source_lines": [
        {
          "line": 1,
          "text": "import { createServer, IncomingMessage } from \"node:http\";"
        },
        {
          "line": 2,
          "text": "import { Entity as EntityV1 } from \"../../generated/ts/v1/entity\";"
        },
        {
          "line": 3,
          "text": "import { Entity as EntityV2 } from \"../../generated/ts/v2/entity\";"
        },
        {
          "line": 4,
          "text": ""
        },
        {
          "line": 5,
          "text": "const observationsHeader = \"X-Schema-Sentinel-Observations\";"
        },
        {
          "line": 6,
          "text": "const traceHeader = \"X-Service-Trace\";"
        },
        {
          "line": 7,
          "text": ""
        },
        {
          "line": 8,
          "text": "export function processEntity(rawBytes: Uint8Array, version: string) {"
        },
        {
          "line": 9,
          "text": "  if (version !== \"v1\" && version !== \"v2\") throw new Error(`Unsupported schema version: ${version}`);"
        },
        {
          "line": 10,
          "text": "  const entity = version === \"v1\" ? EntityV1.decode(rawBytes) : EntityV2.decode(rawBytes);"
        },
        {
          "line": 11,
          "text": "  const fields = { entity_id: entity.entityId, ...(version === \"v1\" ? { name: (entity as EntityV1).name } : {}) };"
        },
        {
          "line": 12,
          "text": "  console.log(JSON.stringify({ runtime: \"typescript\", version, fields }));"
        },
        {
          "line": 13,
          "text": "  return { entity, fields };"
        },
        {
          "line": 14,
          "text": "}"
        },
        {
          "line": 15,
          "text": ""
        },
        {
          "line": 16,
          "text": "async function readBody(request: IncomingMessage): Promise<Buffer> {"
        },
        {
          "line": 17,
          "text": "  const chunks: Buffer[] = [];"
        },
        {
          "line": 18,
          "text": "  for await (const chunk of request) chunks.push(Buffer.from(chunk));"
        },
        {
          "line": 19,
          "text": "  return Buffer.concat(chunks);"
        },
        {
          "line": 20,
          "text": "}"
        },
        {
          "line": 21,
          "text": ""
        },
        {
          "line": 22,
          "text": "if (process.argv.includes(\"--serve\")) {"
        },
        {
          "line": 23,
          "text": "  createServer(async (request, response) => {"
        },
        {
          "line": 24,
          "text": "    if (request.method === \"GET\" && request.url === \"/health\") {"
        },
        {
          "line": 25,
          "text": "      response.writeHead(200, { \"content-type\": \"application/json\" });"
        },
        {
          "line": 26,
          "text": "      response.end(JSON.stringify({ status: \"ok\", runtime: \"typescript\" }));"
        },
        {
          "line": 27,
          "text": "      return;"
        },
        {
          "line": 28,
          "text": "    }"
        },
        {
          "line": 29,
          "text": "    if (request.method !== \"POST\" || request.url !== \"/relay\") {"
        },
        {
          "line": 30,
          "text": "      response.writeHead(404); response.end(); return;"
        },
        {
          "line": 31,
          "text": "    }"
        },
        {
          "line": 32,
          "text": "    try {"
        },
        {
          "line": 33,
          "text": "      const { entity, fields } = processEntity(await readBody(request), \"v1\");"
        },
        {
          "line": 34,
          "text": "      const trace = JSON.parse(String(request.headers[traceHeader.toLowerCase()] ?? \"[]\"));"
        },
        {
          "line": 35,
          "text": "      trace.push(\"typescript\");"
        },
        {
          "line": 36,
          "text": "      const downstream = await fetch(process.env.CSHARP_RELAY_URL ?? \"http://localhost:8002/relay\", {"
        },
        {
          "line": 37,
          "text": "        method: \"POST\","
        },
        {
          "line": 38,
          "text": "        headers: { \"content-type\": \"application/x-protobuf\", [traceHeader]: JSON.stringify(trace) },"
        },
        {
          "line": 39,
          "text": "        body: Buffer.from(EntityV1.encode(entity as EntityV1).finish()),"
        },
        {
          "line": 40,
          "text": "        signal: AbortSignal.timeout(5000),"
        },
        {
          "line": 41,
          "text": "      });"
        },
        {
          "line": 42,
          "text": "      if (!downstream.ok) throw new Error(`C# relay returned ${downstream.status}`);"
        },
        {
          "line": 43,
          "text": "      const body = Buffer.from(await downstream.arrayBuffer());"
        },
        {
          "line": 44,
          "text": "      const observations = [{ runtime: \"typescript\", fields }, ...JSON.parse(downstream.headers.get(observationsHeader) ?? \"null\")];"
        },
        {
          "line": 45,
          "text": "      response.writeHead(200, {"
        },
        {
          "line": 46,
          "text": "        \"content-type\": \"application/x-protobuf\", \"content-length\": body.length,"
        },
        {
          "line": 47,
          "text": "        [observationsHeader]: JSON.stringify(observations).replace(/[\\u007f-\\uffff]/g, c => `\\\\u${c.charCodeAt(0).toString(16).padStart(4, \"0\")}`),"
        },
        {
          "line": 48,
          "text": "        [traceHeader]: downstream.headers.get(traceHeader) ?? \"[]\","
        },
        {
          "line": 49,
          "text": "      });"
        },
        {
          "line": 50,
          "text": "      response.end(body);"
        },
        {
          "line": 51,
          "text": "    } catch (error) {"
        },
        {
          "line": 52,
          "text": "      response.writeHead(400, { \"content-type\": \"application/json\" });"
        },
        {
          "line": 53,
          "text": "      response.end(JSON.stringify({ error: String(error) }));"
        },
        {
          "line": 54,
          "text": "    }"
        },
        {
          "line": 55,
          "text": "  }).listen(Number(process.env.PORT ?? \"8001\"), \"0.0.0.0\");"
        },
        {
          "line": 56,
          "text": "} else {"
        },
        {
          "line": 57,
          "text": "  const version = process.argv.includes(\"--v2\") ? \"v2\" : \"v1\";"
        },
        {
          "line": 58,
          "text": "  const bytes = version === \"v1\""
        },
        {
          "line": 59,
          "text": "    ? EntityV1.encode({ entityId: \"ts_303\", name: \"Sensor C\" }).finish()"
        },
        {
          "line": 60,
          "text": "    : EntityV2.encode({ entityId: \"ts_303\" }).finish();"
        },
        {
          "line": 61,
          "text": "  processEntity(bytes, version);"
        },
        {
          "line": 62,
          "text": "}"
        }
      ]
    }
  ],
